+            <div class="takeaways" aria-label="Takeaway list">
+              <div class="takeaway">
+                <div class="takeawayNum">1</div>
+                <div><strong>Compare within the same Chrome version.</strong> Methodology, throttling, and driver details vary across releases.</div>
+              </div>
+              <div class="takeaway">
+                <div class="takeawayNum">2</div>
+                <div><strong>Use the latest run</strong> (currently Chrome 146) for present-day standings.</div>
+              </div>
+              <div class="takeaway">
+                <div class="takeawayNum">3</div>
+                <div><strong>Keyed vs non-keyed matters.</strong> Recent odd Chrome versions often benchmark keyed frameworks only.</div>
+              </div>
+              <div class="takeaway">
+                <div class="takeawayNum">4</div>
+                <div><strong>Chrome 118 is a scoring boundary.</strong> Weighted geometric mean + throttling changes reshape the aggregate score.</div>
+              </div>
+              <div class="takeaway">
+                <div class="takeawayNum">5</div>
+                <div><strong>60+ data points over ~8 years</strong> make this one of the longest-running framework perf trackers available.</div>
+              </div>
+            </div>
+            <div class="footer" aria-label="Footer">
+              <span class="mono">Built from: /app/benchmark/source_brief.md</span>
+              <span class="mono">Render target: A1 portrait</span>
+            </div>
+          </section>
+
+        </div>
+      </div>
+    </div>
+  </main>
+
+  <script>
+    // === Menu ===
+    function toggleMenu() {
+      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
+      if (dropdown) dropdown.classList.toggle('open');
+    }
+    document.addEventListener('click', function(e) {
+      if (!e.target.closest('.viz-menu')) {
+        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
+        if (dropdown) dropdown.classList.remove('open');
+      }
+    });
+    document.addEventListener('keydown', function(e) {
+      if (e.key === 'Escape') {
+        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
+        if (dropdown) dropdown.classList.remove('open');
+      }
+    });
+
+    // === Theme ===
+    var savedTheme = localStorage.getItem('viz-theme');
+    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
+    function applyTheme(t) {
+      document.documentElement.className = 'theme-' + t;
+      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
+      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
+      localStorage.setItem('viz-theme', t);
+      currentTheme = t;
+      if (typeof onThemeChange === 'function') onThemeChange();
+    }
+    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
+    applyTheme(currentTheme);
+
+    // === Scroll reveal ===
+    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
+    var revealObserver = new IntersectionObserver(function(entries) {
+      entries.forEach(function(e) {
+        if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); }
+      });
+    }, { threshold: 0.12 });
+    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
+
+    // === Number counter ===
+    function animateCounters() {
+      document.querySelectorAll('[data-count]').forEach(function(el) {
+        if (el.dataset.counted) return;
+        el.dataset.counted = '1';
+        var target = parseFloat(el.dataset.count);
+        var prefix = el.dataset.prefix || '';
+        var suffix = el.dataset.suffix || '';
+        var start = performance.now();
+        var duration = 1200;
+        (function tick(now) {
+          var p = Math.min((now - start) / duration, 1);
+          var eased = 1 - Math.pow(1 - p, 3);
+          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
+          if (p < 1) requestAnimationFrame(tick);
+        })(start);
+      });
+    }
+    var counterEl = document.querySelector('[data-count]');
+    if (counterEl) {
+      var cObs = new IntersectionObserver(function(entries) {
+        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
+      }, { threshold: 0.3 });
+      cObs.observe(counterEl);
+    }
+
+    // === Download PNG ===
+    async function downloadImage() {
+      var menu = document.querySelector('.viz-menu');
+      menu.style.display = 'none';
+      try {
+        var poster = document.querySelector('.poster');
+        var url = await htmlToImage.toPng(poster, {
+          quality: 1,
+          pixelRatio: 3,
+          backgroundColor: getComputedStyle(document.body).backgroundColor,
+          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
+        });
+        var a = document.createElement('a');
+        a.href = url;
+        a.download = 'js-framework-benchmark-poster.png';
+        a.click();
+      } catch(e) {
+        console.error('Download failed:', e);
+      }
+      menu.style.display = '';
+    }
+
+    // === Chart.js Manager ===
+    var ChartManager = {
+      charts: new Map(),
+      safeInit: function(canvasId, config) {
+        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
+        try {
+          if (this.charts.has(canvasId)) {
+            this.charts.get(canvasId).destroy();
+            this.charts.delete(canvasId);
+          }
+          var canvas = document.getElementById(canvasId);
+          if (!canvas) { console.error('Canvas element not found: ' + canvasId); return null; }
+          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
+          canvas.setAttribute('role', 'img');
+          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart visualization');
+          var ctx = canvas.getContext('2d');
+          var chart = new Chart(ctx, config);
+          canvas.chart = chart;
+          this.charts.set(canvasId, chart);
+          return chart;
+        } catch (e) {
+          console.error('Chart init failed for ' + canvasId + ':', e);
+          return null;
+        }
+      }
+    };
+
+    var chartsBuilt = false;
+    function buildCharts() {
+      if (chartsBuilt) return;
+      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
+
+      var isDark = document.documentElement.classList.contains('theme-dark');
+      var gridColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
+      var tickColor = isDark ? 'rgba(234,240,255,0.72)' : 'rgba(15,23,42,0.72)';
+
+      var labels = ['2017–2019', '2020', '2021', '2022', '2023', '2024', '2025', '2026'];
+      var values = [4, 5, 9, 13, 12, 12, 12, 3];
+
+      ChartManager.safeInit('runsByYear', {
+        type: 'bar',
+        data: {
+          labels: labels,
+          datasets: [{
+            label: 'Official runs',
+            data: values,
+            backgroundColor: isDark ? 'rgba(59,130,246,0.52)' : 'rgba(37,99,235,0.45)',
+            borderColor: isDark ? 'rgba(45,212,191,0.65)' : 'rgba(15,118,110,0.55)',
+            borderWidth: 1,
+            borderRadius: 8
+          }]
+        },
+        options: {
+          responsive: true,
+          maintainAspectRatio: false,
+          plugins: {
+            legend: { display: false },
+            tooltip: { enabled: true }
+          },
+          scales: {
+            x: {
+              grid: { color: 'transparent' },
+              ticks: {
+                color: tickColor,
+                font: { family: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace', size: 11 }
+              }
+            },
+            y: {
+              beginAtZero: true,
+              suggestedMax: 14,
+              grid: { color: gridColor },
+              ticks: {
+                color: tickColor,
+                precision: 0,
+                font: { family: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace', size: 11 }
+              }
+            }
+          }
+        }
+      });
+
+      chartsBuilt = true;
+    }
+    function onThemeChange() { chartsBuilt = false; buildCharts(); }
+    window.addEventListener('load', function() {
+      // Position the Chrome 118 milestone precisely along the 55→146 axis.
+      var milestone = document.getElementById('milestone118');
+      var badge = document.getElementById('milestoneBadge');
+      if (milestone && badge) {
+        var minV = 55, maxV = 146, v = 118;
+        var p = (v - minV) / (maxV - minV);
+        milestone.style.left = (p * 100) + '%';
+        badge.style.left = (p * 100) + '%';
+      }
+      buildCharts();
+    });
+  </script>
+</body>
+</html>
+
*** End Patch
PATCH"}

