+const path = require('path');
+const fs = require('fs');
+const { chromium } = require('playwright');
+
+function argValue(args, name, fallback) {
+  const idx = args.indexOf(name);
+  if (idx === -1) return fallback;
+  const val = args[idx + 1];
+  if (!val || val.startsWith('--')) return fallback;
+  return val;
+}
+
+async function main() {
+  const args = process.argv.slice(2);
+  const input = argValue(args, '--input');
+  const output = argValue(args, '--output');
+  const width = parseInt(argValue(args, '--width', '2480'), 10);
+  const height = parseInt(argValue(args, '--height', '3508'), 10);
+
+  if (!input || !output) {
+    console.error('Usage: node render_poster.js --input <file.html> --output <file.png> [--width 2480 --height 3508]');
+    process.exit(2);
+  }
+
+  const inputPath = path.resolve(input);
+  const outputPath = path.resolve(output);
+
+  if (!fs.existsSync(inputPath)) {
+    console.error('Input not found:', inputPath);
+    process.exit(2);
+  }
+
+  const browser = await chromium.launch({
+    args: ['--font-render-hinting=medium', '--disable-dev-shm-usage']
+  });
+  const context = await browser.newContext({
+    viewport: { width, height },
+    deviceScaleFactor: 2,
+    colorScheme: 'dark'
+  });
+  const page = await context.newPage();
+
+  page.on('console', (msg) => {
+    if (msg.type() === 'error') console.error('[page console error]', msg.text());
+  });
+  page.on('pageerror', (err) => console.error('[page error]', err));
+
+  await page.goto('file://' + inputPath, { waitUntil: 'networkidle' });
+  await page.waitForTimeout(250);
+
+  // Ensure poster content is fully laid out and charts rendered
+  await page.waitForFunction(() => {
+    const el = document.querySelector('.poster');
+    return !!el && el.getBoundingClientRect().height > 200;
+  });
+  await page.waitForTimeout(250);
+
+  const poster = await page.$('.poster');
+  if (!poster) {
+    console.error('Could not find .poster element to screenshot');
+    process.exit(2);
+  }
+
+  await poster.screenshot({
+    path: outputPath,
+    type: 'png',
+    omitBackground: false
+  });
+
+  await context.close();
+  await browser.close();
+}
+
+main().catch((e) => {
+  console.error(e);
+  process.exit(1);
+});
+
*** End Patch
PATCH

